package io.github.ryosphysrockme.audiosync

import android.content.Context
import android.net.Uri
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicReference

/**
 * Real Android MediaExtractor + MediaCodec and Media3 playback smoke tests.
 *
 * Assets are generated by scripts/generate-audio-format-fixtures.sh before
 * running connectedDebugAndroidTest. The waveforms are synthetic tones.
 */
@RunWith(AndroidJUnit4::class)
class CompressedFormatInstrumentedTest {
    private val instrumentation get() = InstrumentationRegistry.getInstrumentation()
    private val targetContext: Context get() = instrumentation.targetContext

    private fun copyAsset(name: String): File {
        val file = File(targetContext.cacheDir, name)
        instrumentation.context.assets.open(name).use { input ->
            file.outputStream().use { output -> input.copyTo(output) }
        }
        return file
    }

    private fun checkFormat(fileName: String) {
        val file = copyAsset(fileName)
        try {
            val uri = Uri.fromFile(file)
            val frames = ReferenceDecoder.index(context = targetContext, uri = uri)
            assertTrue("Expected > 96 spectral frames for $fileName", frames.size > 96)
            assertTrue("Expected non-silent features for $fileName", frames.count { it.valid } > 96)

            val finished = CountDownLatch(1)
            val error = AtomicReference<String?>(null)
            val player = AtomicReference<LocalPlayback?>(null)

            instrumentation.runOnMainSync {
                val playback = LocalPlayback(targetContext)
                player.set(playback)
                playback.setOnPreparedListener { finished.countDown() }
                playback.setOnErrorListener { p, _, _ ->
                    error.set(p.errorDetail)
                    finished.countDown()
                    true
                }
                playback.setDataSource(uri)
                playback.prepareAsync()
            }
            try {
                assertTrue("Media3 did not prepare $fileName", finished.await(30, TimeUnit.SECONDS))
                assertNull("Media3 failed to prepare $fileName", error.get())
            } finally {
                instrumentation.runOnMainSync { player.get()?.release() }
            }
        } finally {
            file.delete()
        }
    }

    @Test fun mp3ConstantBitrateIndexesAndPrepares() {
        checkFormat("fixture-cbr.mp3")
    }

    @Test fun mp3VariableBitrateIndexesAndPrepares() {
        checkFormat("fixture-vbr.mp3")
    }

    @Test fun m4aAacIndexesAndPrepares() {
        checkFormat("fixture-aac.m4a")
    }
}
